INSERT INTO "fertilizer_types" ("id", "name", "description", "est_days_to_finish") VALUES (1, 'Home aerobic compost', 'Mix suitable kitchen scraps with dry browns in a ventilated bin. The timeline is an estimate; use only mature, earthy compost.', 120) ON CONFLICT DO NOTHING;
INSERT INTO "fertilizer_types" ("id", "name", "description", "est_days_to_finish") VALUES (2, 'Worm compost', 'A dedicated worm bin for suitable small portions of plant scraps. Use appropriate compost worms, bedding and bin-specific guidance.', 120) ON CONFLICT DO NOTHING;
INSERT INTO "fertilizer_types" ("id", "name", "description", "est_days_to_finish") VALUES (3, 'Leafmould soil conditioner', 'Decayed fallen leaves form a soil conditioner rather than a concentrated fertilizer. This is a slower garden-leaf route, not a food-waste bin.', 365) ON CONFLICT DO NOTHING;
