INSERT INTO "fertilizer_maintenance_guides" ("id", "fertilizer_type_id", "check_cadence", "optimal_temp", "moisture_range") VALUES (1, 1, 'Check regularly; follow your bin instructions', 'Varies with system; do not infer temperature from photos', 'Damp like a wrung-out sponge, not saturated') ON CONFLICT DO NOTHING;
INSERT INTO "fertilizer_maintenance_guides" ("id", "fertilizer_type_id", "check_cadence", "optimal_temp", "moisture_range") VALUES (2, 2, 'Check bedding and uneaten food regularly', 'Keep protected from heat and direct sun; follow worm-bin guidance', 'Moist bedding without standing water') ON CONFLICT DO NOTHING;
INSERT INTO "fertilizer_maintenance_guides" ("id", "fertilizer_type_id", "check_cadence", "optimal_temp", "moisture_range") VALUES (3, 3, 'Check occasionally for drying out', 'Ambient decomposition; no temperature claim', 'Moist leaves with drainage') ON CONFLICT DO NOTHING;
INSERT INTO "fertilizer_recipe_steps" ("id", "fertilizer_type_id", "step_number", "instruction") VALUES (1, 1, 1, 'Separate food scraps from packaging, meat, dairy, oil and contaminated materials.') ON CONFLICT DO NOTHING;
INSERT INTO "fertilizer_recipe_steps" ("id", "fertilizer_type_id", "step_number", "instruction") VALUES (2, 1, 2, 'Chop suitable fruit and vegetable scraps into smaller pieces.') ON CONFLICT DO NOTHING;
INSERT INTO "fertilizer_recipe_steps" ("id", "fertilizer_type_id", "step_number", "instruction") VALUES (3, 1, 3, 'Combine the scraps with dry leaves or plain shredded cardboard.') ON CONFLICT DO NOTHING;
INSERT INTO "fertilizer_recipe_steps" ("id", "fertilizer_type_id", "step_number", "instruction") VALUES (4, 1, 4, 'Use a ventilated compost container with drainage; do not seal it airtight.') ON CONFLICT DO NOTHING;
INSERT INTO "fertilizer_recipe_steps" ("id", "fertilizer_type_id", "step_number", "instruction") VALUES (5, 1, 5, 'Keep the mix damp rather than waterlogged and add dry browns if soggy.') ON CONFLICT DO NOTHING;
INSERT INTO "fertilizer_recipe_steps" ("id", "fertilizer_type_id", "step_number", "instruction") VALUES (6, 1, 6, 'Check and aerate the pile as needed for your bin and materials.') ON CONFLICT DO NOTHING;
INSERT INTO "fertilizer_recipe_steps" ("id", "fertilizer_type_id", "step_number", "instruction") VALUES (7, 1, 7, 'Allow curing. Use only when dark, crumbly and earthy; check-ins do not prove maturity.') ON CONFLICT DO NOTHING;
INSERT INTO "fertilizer_recipe_steps" ("id", "fertilizer_type_id", "step_number", "instruction") VALUES (8, 2, 1, 'Choose an appropriate ventilated worm bin and follow the supplier guidance.') ON CONFLICT DO NOTHING;
INSERT INTO "fertilizer_recipe_steps" ("id", "fertilizer_type_id", "step_number", "instruction") VALUES (9, 2, 2, 'Prepare damp plain-paper or cardboard bedding.') ON CONFLICT DO NOTHING;
INSERT INTO "fertilizer_recipe_steps" ("id", "fertilizer_type_id", "step_number", "instruction") VALUES (10, 2, 3, 'Add suitable composting worms; keep the bin shaded and protected.') ON CONFLICT DO NOTHING;
INSERT INTO "fertilizer_recipe_steps" ("id", "fertilizer_type_id", "step_number", "instruction") VALUES (11, 2, 4, 'Feed small amounts of suitable chopped vegetable and fruit scraps.') ON CONFLICT DO NOTHING;
INSERT INTO "fertilizer_recipe_steps" ("id", "fertilizer_type_id", "step_number", "instruction") VALUES (12, 2, 5, 'Cover food with bedding. Avoid meat, dairy, oils and contaminated items.') ON CONFLICT DO NOTHING;
INSERT INTO "fertilizer_recipe_steps" ("id", "fertilizer_type_id", "step_number", "instruction") VALUES (13, 2, 6, 'Check moisture and uneaten food before adding more; adjust for the worms.') ON CONFLICT DO NOTHING;
INSERT INTO "fertilizer_recipe_steps" ("id", "fertilizer_type_id", "step_number", "instruction") VALUES (14, 2, 7, 'Harvest finished castings according to the bin method. Never treat raw drainage as ready fertilizer.') ON CONFLICT DO NOTHING;
INSERT INTO "fertilizer_recipe_steps" ("id", "fertilizer_type_id", "step_number", "instruction") VALUES (15, 3, 1, 'Collect suitable fallen leaves separately from food waste and litter.') ON CONFLICT DO NOTHING;
INSERT INTO "fertilizer_recipe_steps" ("id", "fertilizer_type_id", "step_number", "instruction") VALUES (16, 3, 2, 'Remove plastic, stickers and other contaminants.') ON CONFLICT DO NOTHING;
INSERT INTO "fertilizer_recipe_steps" ("id", "fertilizer_type_id", "step_number", "instruction") VALUES (17, 3, 3, 'Shred large leaves if practical to help them break down.') ON CONFLICT DO NOTHING;
INSERT INTO "fertilizer_recipe_steps" ("id", "fertilizer_type_id", "step_number", "instruction") VALUES (18, 3, 4, 'Place leaves in a ventilated garden enclosure or suitable perforated container.') ON CONFLICT DO NOTHING;
INSERT INTO "fertilizer_recipe_steps" ("id", "fertilizer_type_id", "step_number", "instruction") VALUES (19, 3, 5, 'Moisten dry leaves without leaving them waterlogged.') ON CONFLICT DO NOTHING;
INSERT INTO "fertilizer_recipe_steps" ("id", "fertilizer_type_id", "step_number", "instruction") VALUES (20, 3, 6, 'Check occasionally and allow the leaves time to decay; this can take over a year.') ON CONFLICT DO NOTHING;
INSERT INTO "fertilizer_recipe_steps" ("id", "fertilizer_type_id", "step_number", "instruction") VALUES (21, 3, 7, 'Use only well-rotted leafmould for an appropriate garden purpose; avoid treating it as a nutrient concentrate.') ON CONFLICT DO NOTHING;
